// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Product, Fixed18, PackedFixed18, PackedUFixed18, UFixed18, IOracleProvider, JumpRateUtilizationCurve, PayoffDefinition, PayoffDefinitionLib, IProduct} from "../src/Product.sol";

contract InvMutTest is Test {
    Product c;

    function setUp() public { c = new Product(); }

    function testFuzz_property(address owner, address caller, uint256 rawValue) public {
        vm.assume(owner != address(0));
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // Adversarial environment: a controller the product is bound to, plus an oracle
        // whose version equals the product's latest version so settle() is a no-op.
        MockOracle o = new MockOracle();
        MockController mc = new MockController();
        mc.setCoordinatorOwner(owner);

        PayoffDefinition memory pd = PayoffDefinition(
            PayoffDefinitionLib.PayoffType(0),
            PayoffDefinitionLib.PayoffDirection(0),
            bytes30(0)
        );
        IProduct.ProductInfo memory info = IProduct.ProductInfo(
            "T",
            "T",
            pd,
            IOracleProvider(address(o)),
            UFixed18.wrap(1e18),   // maintenance
            UFixed18.wrap(0),      // fundingFee
            UFixed18.wrap(0),      // makerFee
            UFixed18.wrap(0),      // takerFee
            UFixed18.wrap(0),      // positionFee
            UFixed18.wrap(1e18),   // makerLimit
            JumpRateUtilizationCurve(
                PackedFixed18.wrap(0),
                PackedFixed18.wrap(0),
                PackedFixed18.wrap(0),
                PackedUFixed18.wrap(0)
            )
        );
        vm.prank(address(mc));
        c.initialize(info);

        UFixed18 newVal = UFixed18.wrap(rawValue);

        vm.prank(caller);
        bool ok;
        try c.updateMaintenance(newVal) { ok = true; } catch { ok = false; }

        // General rule: for EVERY caller and value, updateMaintenance succeeds exactly
        // when the caller is the coordinator owner, and when it succeeds the stored
        // maintenance equals exactly the requested value.
        assertTrue(ok == (caller == owner) && (!ok || UFixed18.unwrap(c.maintenance()) == rawValue));
    }
}

contract MockOracle {
    function sync() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }

    function currentVersion() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }

    function atVersion(uint256) external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }
}

contract MockController {
    address private coordinatorOwner;

    function setCoordinatorOwner(address a) external { coordinatorOwner = a; }

    function paused() external pure returns (bool) { return false; }

    function coordinatorFor(IProduct) external pure returns (uint256) { return 0; }

    function owner(uint256) external view returns (address) { return coordinatorOwner; }

    fallback() external { revert(); }
}
